package au.aumanet.app;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import androidx.core.content.ContextCompat;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Visible user-started VPN/donation owner. Never sticky and never started at boot. */
public final class InternetSharingService extends VpnService {
 private static final String CHANNEL="aumanet-internet-sharing",STOP="au.aumanet.internet.STOP";
 private static final Object LOCK=new Object();private static volatile InternetSharingService active;private static volatile boolean draining,nativeDraining;private static int pendingNativeStops;private static volatile ParcelFileDescriptor strandedTun;
 private InternetSharingController controller;private volatile ParcelFileDescriptor tun;private volatile boolean engineBlocked;private PowerManager.WakeLock wake;
 private final Handler main=new Handler(Looper.getMainLooper());private final AtomicBoolean stopping=new AtomicBoolean();
 private final ExecutorService engine=Executors.newSingleThreadExecutor();
 static boolean engineAvailable(){try{return Build.VERSION.SDK_INT>=29&&hev.htproxy.TProxyService.TProxyIsRunning()||Build.VERSION.SDK_INT>=29;}catch(Throwable absent){return false;}}
 static boolean availableForStart(){synchronized(LOCK){return !draining&&!nativeDraining&&(active==null||!active.stopping.get());}}
 static void start(Context context)throws Exception{synchronized(LOCK){if(draining||nativeDraining||active!=null&&active.stopping.get())throw new IllegalStateException("Previous internet service is stopping");if(!ServiceNotificationAccess.allowed(context,CHANNEL))throw new IllegalStateException("Enable internet sharing notifications");ContextCompat.startForegroundService(context,new Intent(context,InternetSharingService.class));}}
 @Override public void onCreate(){super.onCreate();try{controller=InternetSharingController.get(this);synchronized(LOCK){active=this;}NotificationManager notifications=getSystemService(NotificationManager.class);notifications.createNotificationChannel(new NotificationChannel(CHANNEL,"Shared internet",NotificationManager.IMPORTANCE_LOW));startForeground(4821,notification());wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"AuMaNET:Internet");wake.setReferenceCounted(false);wake.acquire(InternetSharingPolicy.MAX_MS);controller.serviceReady(this);main.postDelayed(health,1000);}catch(Exception failed){if(controller!=null)controller.serviceDestroyed(this);stopSelf();}}
 private Notification notification(){Intent stop=controller.notificationStopIntent(new Intent(this,InternetSharingService.class).setAction(STOP));String token=stop.getStringExtra("donor")+":"+stop.getStringExtra("consumer");stop.setData(android.net.Uri.parse("aumanet://internet/stop/"+android.net.Uri.encode(token)));PendingIntent action=PendingIntent.getService(this,token.hashCode(),stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.stat_sys_upload_done).setContentTitle("AuMaNET shared internet").setContentText("Sharing or using mobile data · Stop disconnects shared internet").setOngoing(true).setContentIntent(open).addAction(new Notification.Action.Builder(null,"Stop shared internet",action).build()).build();}
 @Override public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&STOP.equals(intent.getAction())){if(controller!=null)controller.stopNotification(intent);finishIfIdle();return START_NOT_STICKY;}if(controller!=null)controller.serviceReady(this);refreshNotification();if(wake!=null)wake.acquire(InternetSharingPolicy.MAX_MS);return START_NOT_STICKY;}
 private final Runnable health=new Runnable(){public void run(){if(stopping.get())return;if(controller==null||!controller.active()){finishIfIdle();return;}main.postDelayed(this,1000);}};
 boolean usable(){return active==this&&!stopping.get();}
 void refreshNotification(){main.post(()->{if(usable())getSystemService(NotificationManager.class).notify(4821,notification());});}
 boolean engineRunning(){try{return tun!=null&&!engineBlocked&&hev.htproxy.TProxyService.TProxyIsRunning();}catch(Throwable failed){return false;}}
 boolean tunActive(){return tun!=null;}
 synchronized void startTunnel(int port,String user,String password,Network selected)throws Exception{
  if(tun!=null)return;synchronized(LOCK){if(nativeDraining)throw new IOException("Previous VPN engine is stopping");}if(hev.htproxy.TProxyService.TProxyIsRunning())throw new IOException("Previous VPN engine is stopping");if(VpnService.prepare(this)!=null)throw new SecurityException("VPN permission required");
  Builder builder=new Builder().setSession("AuMaNET selected shared internet").setMtu(1280).addAddress("10.250.0.2",32).addAddress("fd61:756d:616e::2",128).addDnsServer("1.1.1.1").addRoute("::",0).setMetered(true);
  // All IPv4 except the authenticated mesh management/data LAN. No app bypass.
  addRoutesExcept(builder,0,0,0x0a4d0000L,24);builder.setUnderlyingNetworks(new Network[]{selected});
  ParcelFileDescriptor opened=builder.establish();if(opened==null)throw new IOException("VPN permission revoked");
  boolean adopted=false;try{File config=new File(getNoBackupFilesDir(),"internet-tunnel-v1.yml");String yaml="tunnel:\n  mtu: 1280\n  ipv4: 10.250.0.2\nsocks5:\n  address: 127.0.0.1\n  port: "+port+"\n  udp: udp\n  username: '"+user+"'\n  password: '"+password+"'\nmisc:\n  task-stack-size: 36864\n  tcp-buffer-size: 16384\n  max-session-count: 24\n  connect-timeout: 10000\n  tcp-read-write-timeout: 120000\n  udp-read-write-timeout: 60000\n  log-level: error\n  log-file: /dev/null\n";
  try(FileOutputStream out=new FileOutputStream(config)){out.write(yaml.getBytes(java.nio.charset.StandardCharsets.US_ASCII));out.getFD().sync();}
  if(!hev.htproxy.TProxyService.TProxyStartService(config.getAbsolutePath(),opened.getFd()))throw new IOException("VPN engine is busy");tun=opened;engineBlocked=false;adopted=true;
  }finally{if(!adopted)opened.close();}
 }
 private static void addRoutesExcept(Builder builder,long network,int prefix,long excluded,int excludedPrefix)throws Exception{long mask=prefix==0?0:(0xffffffffL<<(32-prefix))&0xffffffffL;if((network&mask)!=(excluded&mask)||prefix>=excludedPrefix){if(prefix>=excludedPrefix&&(network&mask)==(excluded&mask))return;byte[] bytes={(byte)(network>>24),(byte)(network>>16),(byte)(network>>8),(byte)network};builder.addRoute(java.net.InetAddress.getByAddress(bytes),prefix);return;}long bit=1L<<(31-prefix);addRoutesExcept(builder,network,prefix+1,excluded,excludedPrefix);addRoutesExcept(builder,network|bit,prefix+1,excluded,excludedPrefix);}
 private void stopEngine(ParcelFileDescriptor closing){synchronized(LOCK){pendingNativeStops++;nativeDraining=true;}try{engine.execute(()->{try{hev.htproxy.TProxyService.TProxyStopService();}catch(Throwable ignored){}finally{if(closing!=null)try{closing.close();}catch(Exception ignored){}synchronized(LOCK){pendingNativeStops--;nativeDraining=pendingNativeStops>0;if(active==null&&!nativeDraining)draining=false;}}});}catch(RejectedExecutionException stopped){synchronized(LOCK){strandedTun=closing;draining=nativeDraining=true;}}}
 synchronized void stopTunnel(){ParcelFileDescriptor own=tun;if(own==null)return;tun=null;engineBlocked=true;stopEngine(own);}
 /** Automatic expiry/revocation retires forwarding but never restores normal internet. */
 synchronized void blockTunnel(){if(tun==null||engineBlocked)return;engineBlocked=true;stopEngine(null);if(wake!=null&&wake.isHeld()&&(controller==null||!controller.forwardingActive()))wake.release();}
 void finishIfIdle(){main.post(()->{synchronized(LOCK){if(controller!=null&&controller.active()||!stopping.compareAndSet(false,true))return;draining=true;}stopTunnel();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();});}
 @Override public void onRevoke(){if(controller!=null)controller.revoked();stopTunnel();finishIfIdle();}
 @Override public void onDestroy(){stopping.set(true);main.removeCallbacksAndMessages(null);if(controller!=null)controller.serviceDestroyed(this);stopTunnel();if(wake!=null&&wake.isHeld())wake.release();synchronized(LOCK){if(active==this)active=null;if(!nativeDraining)draining=false;}engine.shutdown();super.onDestroy();}
}

